const CACHE='dynasty-desk-v3';const ASSETS=['./','./index.html','./styles.css','./app.js','./domain/models.js','./domain/simulation.js','./stores/local.js','./stores/game-store.js','./manifest.webmanifest'];self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(ASSETS)).then(()=>self.skipWaiting())));self.addEventListener('activate',e=>e.waitUntil(self.clients.claim()));self.addEventListener('fetch',e=>e.respondWith(caches.match(e.request).then(r=>r||fetch(e.request))));
